let state = "closed";
let failures = 0;
let openedAt = 0;
const log: string[] = [];

function call(now: number, works: boolean): void {
  if (state === "open" && now - openedAt >= 1_000) state = "half-open";
  if (state === "open") {
    log.push(`${now}:fast-fail`);
    return;
  }
  if (works) {
    failures = 0;
    state = "closed";
    log.push(`${now}:ok`);
  } else {
    failures++;
    if (state === "half-open" || failures >= 2) {
      state = "open";
      openedAt = now;
    }
    log.push(`${now}:fail`);
  }
}

