class CircuitBreaker {
  state: "closed" | "open" | "half-open" = "closed";
  private failures = 0;
  private openedAt = 0;

  allows(now: number): boolean {
    if (this.state === "open" && now - this.openedAt >= 5_000) this.state = "half-open";
    return this.state !== "open";
  }

  succeeded(): void {
    this.failures = 0;
    this.state = "closed";
  }

  failed(now: number): void {
    this.failures++;
    if (this.state === "half-open" || this.failures >= 3) {
      this.state = "open";
      this.openedAt = now;
    }
  }
}

const breaker = new CircuitBreaker();
const states: string[] = [];
breaker.failed(0); states.push(breaker.state);
breaker.failed(100); states.push(breaker.state);
breaker.failed(200); states.push(breaker.state);
breaker.allows(3_000); states.push(breaker.state);
breaker.allows(5_300); states.push(breaker.state);
breaker.succeeded(); states.push(breaker.state);
