const catalog = async (id: string) => {
  if (id === "b9") throw new Error("catalog down");
  return { title: "Things Fall Apart" };
};
const reviews = async (id: string) => {
  if (id === "b2") throw new Error("reviews timed out");
  return [5, 4];
};

async function bookPage(bookId: string): Promise<{ status: number; body?: { title: string; reviews: number | string } }> {
  const [book, scores] = await Promise.allSettled([catalog(bookId), reviews(bookId)]);
  if (book.status === "rejected") return { status: 503 };
  const rating = scores.status === "fulfilled" ? scores.value.reduce((a, b) => a + b, 0) / scores.value.length : "unavailable";
  return { status: 200, body: { title: book.value.title, reviews: rating } };
}

const a = await bookPage("b1");
