function moduleOf(path: string): string | undefined {
  return /^src\/modules\/([\w-]+)\//.exec(path)?.[1];
}

function crossesBoundary(from: string, target: string): boolean {
  const to = moduleOf(target);
  if (to === undefined || to === moduleOf(from)) return false;
  return target !== `src/modules/${to}/index.ts`;
}

