function consume(ackFirst: boolean): string[] {
  const queue = ["msg-1", "msg-2", "msg-3"];
  const done: string[] = [];
  let crashed = false;
  while (queue.length > 0) {
    const id = queue[0]!;
    if (ackFirst) queue.shift();
    if (id === "msg-2" && !crashed) {
      crashed = true;
      continue;
    }
    done.push(id);
    if (!ackFirst) queue.shift();
  }
  return done;
}

