const values = [0.5, 0.5, 0.75, 0.5];
let i = 0;
const fakeRandom = () => values[i++ % values.length]!;

function retryDelays(attempts: number, base: number, cap: number, random: () => number): number[] {
  const delays: number[] = [];
  for (let n = 1; n <= attempts; n++) {
    const limit = Math.min(cap, base * 2 ** (n - 1));
    delays.push(Math.floor(random() * limit));
  }
  return delays;
}

console.log(retryDelays(4, 100, 800, fakeRandom));

