type ShopEvent =
  | { type: "order.placed"; lines: { title: string; quantity: number }[] }
  | { type: "order.cancelled"; orderId: string };

const events: ShopEvent[] = [
  { type: "order.placed", lines: [{ title: "Things Fall Apart", quantity: 2 }] },
  { type: "order.placed", lines: [{ title: "Purple Hibiscus", quantity: 4 }, { title: "Things Fall Apart", quantity: 1 }] },
  { type: "order.cancelled", orderId: "ord-9" },
  { type: "order.placed", lines: [{ title: "Purple Hibiscus", quantity: 1 }] },
];

function bestSellers(all: ShopEvent[]): string[] {
  const copies = new Map<string, number>();
  for (const event of all) {
    if (event.type !== "order.placed") continue;
    for (const line of event.lines) copies.set(line.title, (copies.get(line.title) ?? 0) + line.quantity);
  }
  return [...copies].sort((a, b) => b[1] - a[1]).map(([title, n]) => `${title}: ${n}`);
}

console.log(bestSellers(events));

